const config = $('Set Cleanup Config').first().json;
const masterFileByGame = {
  CBM_TH: '1ofe69uOTknTY2RcoLjAkPXUQ0sUQjZPgJ-oIRCD5hKM',
  CBM_SEA: '1B_eXcoxJyKnV_wH4zyPHqDg2lmS_gfGJ-9cxaF5h5bY',
