  CBPC_SEA: '1p5qN81Vg5rN08XldlQDV_fQTuqRaS1xpBk-aWuQb-9I'
};
function splitIds(value) {
  return String(value || '')
    .split(/[\s,]+/)
    .map(v => v.trim())
    .filter(Boolean);
}
const runIds = splitIds(config.run_id);
const cleanupHashes = splitIds(config.cleanup_hash);
const master_file_id = masterFileByGame[config.target_game_code] || '';
const warnings = [];
if (!master_file_id) warnings.push(`Unknown target_game_code: ${config.target_game_code}`);
if (!config.target_month) warnings.push('target_month is required');
