const config = $('Resolve Master File').first().json;
const masterTabs = ['RawImports','UserCohort','ChannelDaily','ChannelWeekly','ChannelMonthly','DAUDaily','Returners','LateFirstLogin','QualitySignals','TransformLog'];
function rowsFrom(nodeName) {
  try { return $(nodeName).all().map((item, idx) => ({...item.json, _n8n_index: idx + 1})).filter(row => !row.error); }
  catch (error) { return []; }
}
function rowNumber(row) { return Number(row.row_number || row.__rowNumber || row._rowNumber || row._n8n_index || 0); }
function period(row) { return String(row.period_key || row.month || ''); }
function normalizeList(values) {
  return [...new Set((values || []).map(v => String(v || '').trim()).filter(Boolean))];
}
const targetRunIds = normalizeList(config.run_ids && config.run_ids.length ? config.run_ids : String(config.run_id || '').split(/[\s,]+/));
const explicitCleanupHashes = normalizeList(config.cleanup_hashes && config.cleanup_hashes.length ? config.cleanup_hashes : String(config.cleanup_hash || '').split(/[\s,]+/));
function sameGameMonth(row) {
  return String(row.game_code || '') === String(config.target_game_code || '') &&
    period(row) === String(config.target_month || '');
}
function matchesRun(row) {
  return targetRunIds.length > 0 && targetRunIds.includes(String(row.run_id || ''));
}
function cleanupHashFromRun(row) {
  const status = String(row.status || '').toLowerCase();
  if (status === 'needs_review') return String(row.data_hash_before || '').trim();
  return String(row.data_hash || row.data_hash_after || row.data_hash_before || '').trim();
}
const pipelineRows = rowsFrom('Read Central DB - PipelineLogs');
const transformRows = rowsFrom('Read Master - TransformLog');
const runMatchedRows = [...pipelineRows, ...transformRows].filter(row => sameGameMonth(row) && matchesRun(row));
let dataHashCandidates = normalizeList([
  ...explicitCleanupHashes,
  ...runMatchedRows.map(cleanupHashFromRun)
]);
function matchesHash(row) {
  return dataHashCandidates.length > 0 && dataHashCandidates.includes(String(row.data_hash || row.data_hash_before || row.data_hash_after || '').trim());
}
function isTargetRow(row) {
  return sameGameMonth(row) && (matchesRun(row) || matchesHash(row));
}
function summarizeMatches(rows) {
  const matches = rows.filter(isTargetRow);
  const rowNumbers = matches.map(rowNumber).filter(Boolean).sort((a,b)=>b-a);
  return { count: matches.length, row_numbers_desc: rowNumbers, sample_row_numbers_desc: rowNumbers.slice(0, 20) };
}
const masterPreview = {};
for (const tab of masterTabs) masterPreview[tab] = summarizeMatches(rowsFrom(`Read Master - ${tab}`));
const centralPreview = {};
centralPreview.PipelineLogs = summarizeMatches(pipelineRows);
const dataIndexRows = rowsFrom('Read Central DB - DataIndex');
const dataIndexMatches = dataIndexRows.filter(row =>
  sameGameMonth(row) && dataHashCandidates.includes(String(row.data_hash || '').trim())
);
centralPreview.DataIndex = {
  count: dataIndexMatches.length,
  row_numbers_desc: dataIndexMatches.map(rowNumber).filter(Boolean).sort((a,b)=>b-a),
  sample_row_numbers_desc: dataIndexMatches.map(rowNumber).filter(Boolean).sort((a,b)=>b-a).slice(0,20)
};
const cacheRows = rowsFrom('Read Central DB - AISummaryCache');
const cacheMatches = cacheRows.filter(row => {
  const sameRun = matchesRun(row);
  const sameHash = dataHashCandidates.includes(String(row.data_hash || '').trim());
  return sameGameMonth(row) && (sameRun || (config.delete_ai_summary_cache === true && sameHash));
});
centralPreview.AISummaryCache = {
  count: cacheMatches.length,
  row_numbers_desc: cacheMatches.map(rowNumber).filter(Boolean).sort((a,b)=>b-a),
  sample_row_numbers_desc: cacheMatches.map(rowNumber).filter(Boolean).sort((a,b)=>b-a).slice(0,20),
  delete_requires_explicit_flag: true
};
const totalMasterRows = Object.values(masterPreview).reduce((s,t)=>s+t.count,0);
const totalCentralRows = Object.values(centralPreview).reduce((s,t)=>s+t.count,0);
const warnings = [...(config.warnings || [])];
if (config.confirm_delete === 'YES') warnings.push('DELETE REQUESTED. This delete-enabled workflow will delete only the previewed rows after this preview step.');
if (!dataHashCandidates.length) warnings.push('No cleanup hash candidates found. DataIndex cleanup preview may be empty.');
return [{ json: {
  workflow_status: config.confirm_delete === 'YES' ? 'delete_confirmed_ready' : 'preview_only_no_delete',
  target_game_code: config.target_game_code,
  target_month: config.target_month,
  run_id: config.run_id,
  run_ids: targetRunIds,
  cleanup_hash: config.cleanup_hash,
  confirm_delete: config.confirm_delete,
  central_db_id: config.central_db_id,
  master_file_id: config.master_file_id,
  data_hash_candidates: dataHashCandidates,
  master_rows_to_delete_by_tab: masterPreview,
  central_rows_to_delete_by_tab: centralPreview,
  total_master_rows_to_delete: totalMasterRows,
  total_central_rows_to_delete: totalCentralRows,
  delete_order: 'bottom_to_top',
  destructive_delete_executed: false,
  warnings
}}];

