const p = $json;
if (p.confirm_delete !== 'YES') return [];
function groupDescendingRows(rowNumbers) {
  const rows = [...new Set((rowNumbers || []).map(Number).filter(n => Number.isFinite(n) && n > 1))].sort((a, b) => b - a);
  const ranges = [];
  let high = null;
  let low = null;
  for (const row of rows) {
    if (high === null) { high = row; low = row; continue; }
    if (row === low - 1) { low = row; continue; }
    ranges.push({ start_row_number: low, number_of_rows_to_delete: high - low + 1, highest_row_number: high });
    high = row;
    low = row;
  }
  if (high !== null) ranges.push({ start_row_number: low, number_of_rows_to_delete: high - low + 1, highest_row_number: high });
  return ranges.sort((a, b) => b.highest_row_number - a.highest_row_number);
}
const rangesByKey = {};
function addRanges(area, documentId, tab, rowNumbers) {
  const key = area + '|' + tab;
  rangesByKey[key] = groupDescendingRows(rowNumbers).map(r => ({
    area,
    document_id: documentId,
    sheet_name: tab,
    start_row_number: r.start_row_number,
    number_of_rows_to_delete: r.number_of_rows_to_delete,
    highest_row_number: r.highest_row_number,
    target_game_code: p.target_game_code,
    target_month: p.target_month,
    cleanup_target_run_id: p.run_id,
    cleanup_data_hash_candidates: p.data_hash_candidates || []
  }));
}
for (const [tab, info] of Object.entries(p.master_rows_to_delete_by_tab || {})) addRanges('master', p.master_file_id, tab, info.row_numbers_desc || []);
for (const [tab, info] of Object.entries(p.central_rows_to_delete_by_tab || {})) addRanges('central_db', p.central_db_id, tab, info.row_numbers_desc || []);
