const rows_to_delete = Object.values(rangesByKey).flat().reduce((sum, row) => sum + Number(row.number_of_rows_to_delete || 0), 0);
return [{ json: { ...p, rangesByKey, delete_range_count, rows_to_delete, no_delete_ranges: delete_range_count === 0 } }];
